INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q123215', 'Battle of Jaxartes', 'The Battle of Jaxartes was fought in 329 BC by Alexander the Great and his Hellenic (Greek) army against the Saka at the River Jaxartes, now known as the Syr Darya River. The site of the battle straddles the modern borders of Uzbekistan, Tajikistan, Kyrgyzstan, and Kazakhstan, just south-west of the ancient city of Tashkent (the modern capital of Uzbekistan) and north-east of Khujand (a city in Tajikistan).', -329, 10, NULL, NULL, NULL, NULL, 'month', 'October 329 BCE', 56, 'https://en.wikipedia.org/wiki/Battle_of_Jaxartes'),
  ('Q7509958', 'Siege of Cyropolis', 'Cyropolis was the largest of seven towns in the region that Alexander the Great targeted for conquest in 329 BC. His goal was the conquest of Sogdiana. Alexander first sent Craterus to Cyropolis, the largest of the Sogdian towns holding out against Alexander''s forces.', -329, NULL, NULL, NULL, NULL, NULL, 'year', '329 BCE', 41, 'https://en.wikipedia.org/wiki/Siege_of_Cyropolis'),
  ('Q5242954', 'Day of Thirst', 'The "Day of Thirst" (Arabic: ﻳﻮﻢ ﺍلعطش, romanized: Yawm al-aṭash) is the name traditionally given in Arabic historiography to a battle fought in 724 between the Turkic Türgesh Khaganate and the Umayyad Caliphate on the banks of the Syr Darya river, in Transoxiana (in modern Tajikistan, Central Asia). The Umayyad army, under Muslim ibn Sa''id al-Kilabi, was campaigning in the Ferghana Valley when it learned of the Türgesh advance.', 724, NULL, NULL, NULL, NULL, NULL, 'year', '724', 51, 'https://en.wikipedia.org/wiki/Day_of_Thirst'),
  ('Q4558717', '1907 Qaratog earthquake', 'The 1907 Qaratog earthquake occurred at 04:23 UTC on 21 October near Qaratog (Karatag) in the border area between Uzbekistan and Tajikistan, then part of the Russian Empire. The shock had an estimated surface-wave magnitude of 7.4 and a maximum felt intensity of IX (Violent) on the Mercalli intensity scale.', 1907, 10, 21, NULL, NULL, NULL, 'day', '21 October 1907', 39, 'https://en.wikipedia.org/wiki/1907_Qaratog_earthquake'),
  ('Q5937456', '1989 Gissar earthquake', 'The 1989 Gissar earthquake occurred at 23:02 UTC on 22 January near Gissar in Tajikistan. The shock had a body wave magnitude of 5.3 and a maximum felt intensity of VII (Very strong) on the Mercalli intensity scale.', 1989, 1, 22, NULL, NULL, NULL, 'day', '22 January 1989', 37, 'https://en.wikipedia.org/wiki/1989_Gissar_earthquake'),
  ('Q1122110', 'Tajikistani Civil War', 'The Tajikistani Civil War was an armed conflict in Tajikistan that began in May 1992 and ended in June 1997. Regional groups from the Garm and Gorno-Badakhshan regions of Tajikistan rose up against the newly formed government of President Rahmon Nabiyev, which was dominated by people from the Khujand and Kulob regions.', 1992, 5, 5, 1997, 6, 27, 'day', '5 May 1992 – 27 June 1997', 72, 'https://en.wikipedia.org/wiki/Tajikistani_Civil_War'),
  ('Q7676834', 'Tajikistani constitutional referendum, 1994', 'A constitutional referendum was held in Tajikistan on 6 November 1994. The new constitution was approved by 96% of voters.', 1994, 11, 6, NULL, NULL, NULL, 'day', '6 November 1994', 43, 'https://en.wikipedia.org/wiki/1994_Tajik_constitutional_referendum'),
  ('Q7676835', 'Tajikistani constitutional referendum, 1999', 'A constitutional referendum was held in Tajikistan on 26 September 1999. The changes included legalising religious political parties, introducing a bicameral parliament, and lengthening the president''s term from five to seven years.', 1999, 9, 26, NULL, NULL, NULL, 'day', '26 September 1999', 39, 'https://en.wikipedia.org/wiki/1999_Tajik_constitutional_referendum'),
  ('Q7676836', 'Tajikistani constitutional referendum, 2003', 'A constitutional referendum was held in Tajikistan on 22 June 2003. The changes included removing Article 65, which limited the President to a single term of office.', 2003, 6, 22, NULL, NULL, NULL, 'day', '22 June 2003', 41, 'https://en.wikipedia.org/wiki/2003_Tajik_constitutional_referendum'),
  ('Q4607001', '2006 Tajikistan earthquake', 'On July 29, the 2006 Tajikistan earthquake hit the Khatlon region of Tajikistan. The earthquake doublet killed four people and injured 40 in both Tajikistan and Afghanistan.', 2006, 7, 29, 2006, 7, 29, 'day', '29 July 2006', 34, 'https://en.wikipedia.org/wiki/2006_Tajikistan_earthquake');

